var a=[{title:`Prima settimana: impara la routine`,text:`Scegli due brevi sessioni total body e fai camminate facili negli altri giorni se te la senti. Esercita gli schemi base di squat, hinge, spinta, trazione e core con movimenti adatti alla tua attrezzatura e al tuo corpo. Una prima sessione può essere di una o due serie di diversi esercizi.`},{title:`Settimane da due a quattro: ripeti e osserva`,text:`Mantieni gli stessi esercizi, poi aggiungi lentamente ripetizioni, un po’ di carico o una serie in più se stai recuperando bene. Piccoli aumenti che riesci a mantenere ti aiutano a costruire fiducia. Non leggere ogni nuova sensazione o ogni po’ di dolore muscolare come un motivo per cambiare tutto il piano.`},{title:`Esempio`,text:`Il lunedì e il giovedì, fai squat alla sedia controllati, rematori con appoggio, push-up al muro e una breve tenuta per il core. Aggiungi una camminata comoda in un altro giorno. Se un movimento è troppo difficile, scegli una versione più facile. Se è molto facile, rendilo più difficile gradualmente mantenendo il controllo.`},{title:`Cosa aspettarsi all’inizio`,text:`I primi guadagni di forza spesso derivano da una migliore abilità e coordinazione tra nervi e muscoli, e i cambiamenti fisici si vedono di più col tempo. Un allenamento saltato non cancella i tuoi progressi. Riprendi semplicemente alla sessione successiva prevista.`},{title:`Usare TrainUp`,text:`Imposta onestamente il tuo livello di forma in Profilo, insieme all’attrezzatura che hai e alla durata della sessione. Dopo ogni allenamento, valuta il tuo sforzo (RPE). Il tuo piano cambia solo quando lo rigeneri, e mai partendo da meno di 3 allenamenti. Se i tuoi ultimi 4 sono stati facili (RPE 5 o meno) e completi, il piano successivo sale di un gradino.`}];var o=[{label:`Indicazioni pratiche ACSM 2026`,url:`https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf`},{label:`NHS: camminare per la salute`,url:`https://www.nhs.uk/live-well/exercise/walking-for-health/`}];var t={sections:a,sources:o};export{t as default,a as sections,o as sources};